import java.util.List;
import sailpoint.object.Capability;

if (identity == null) return false;
List caps = identity.getCapabilityManager().getEffectiveCapabilities();
if (caps == null) return false;
for (Object c : caps) {
    String n = ((Capability) c).getName();
    if ("SystemAdministrator".equals(n) || "EmergencyIdentityAdministrator".equals(n)) return true;
}
return false;
